select IFNULL(ROUND(SUM(gdgsr.gb_dgsr_subtotal), 1), 0) from gb_department_goods_stock_reduce as gdgsr
left join gb_department as gd on gd.gb_department_id = gdgsr.gb_dgsr_gb_department_id
left join gb_distributer_goods as gdd on gdd.gb_distributer_goods_id = gdgsr.gb_dgsr_gb_dis_goods_id


        and gdgsr.gb_dgsr_type = #{params.type}


