        and gd.gb_department_type = #{params.depType}


        and gdgsr.gb_dgsr_gb_department_id = #{params.depId}


        and gdgsr.gb_dgsr_date >= #{params.startDate}


        and gdgsr.gb_dgsr_date <= #{params.stopDate}


        and (
            gdgsr.gb_dgsr_gb_dis_goods_great_id = #{params.disGoodsGreatId}
            or gdd.gb_dg_dfg_goods_great_id = #{params.disGoodsGreatId}
        )


        and gdgsr.gb_dgsr_stock_nx_supplier_id = #{params.supplierId}


        and gdgsr.gb_dgsr_stock_pur_user_id = #{params.purUserId}

select
    IFNULL(ROUND(SUM(case when r.gb_dgsr_type = 1 then r.gb_dgsr_subtotal else 0 end), 1), 0) as produceTotal,
    IFNULL(ROUND(SUM(case when r.gb_dgsr_type = 2 then r.gb_dgsr_subtotal else 0 end), 1), 0) as wasteTotal,
    IFNULL(ROUND(SUM(case when r.gb_dgsr_type = 3 then r.gb_dgsr_subtotal else 0 end), 1), 0) as lossTotal,
    IFNULL(ROUND(SUM(case when r.gb_dgsr_type = 4 then r.gb_dgsr_subtotal else 0 end), 1), 0) as returnTotal
from gb_department_goods_stock_reduce r
left join gb_department gd on gd.gb_department_id = r.gb_dgsr_gb_department_father_id
left join gb_distributer_goods gdd on gdd.gb_distributer_goods_id = r.gb_dgsr_gb_dis_goods_id


        and r.gb_dgsr_gb_department_father_id = #{params.departmentFatherId}


        and r.gb_dgsr_gb_department_id = #{params.departmentId}


        and r.gb_dgsr_gb_distributer_id = #{params.disId}


        and r.gb_dgsr_gb_department_id = #{params.depId}


        and gd.gb_department_type = #{params.depType}


        and r.gb_dgsr_date >= #{params.startDate}


        and r.gb_dgsr_date <= #{params.stopDate}


        and (
            r.gb_dgsr_gb_dis_goods_great_id = #{params.disGoodsGreatId}
            or gdd.gb_dg_dfg_goods_great_id = #{params.disGoodsGreatId}
        )

select count(distinct gsr.gb_dgsr_gb_dis_goods_id)
from gb_department_goods_stock_reduce gsr
left join gb_department gd on gd.gb_department_id = gsr.gb_dgsr_gb_department_id
left join gb_distributer_goods dg on dg.gb_distributer_goods_id = gsr.gb_dgsr_gb_dis_goods_id


        and gsr.gb_dgsr_gb_distributer_id = #{params.disId}


        and gsr.gb_dgsr_gb_department_id = #{params.depId}


        and gd.gb_department_type = #{params.depType}


        and gsr.gb_dgsr_date >= #{params.startDate}


        and gsr.gb_dgsr_date <= #{params.stopDate}


        and (
            gsr.gb_dgsr_gb_dis_goods_great_id = #{params.disGoodsGreatId}
            or dg.gb_dg_dfg_goods_great_id = #{params.disGoodsGreatId}
        )


        and gsr.gb_dgsr_type = #{params.type}


        and gsr.gb_dgsr_type in

            #{typeItem}



        and gsr.gb_dgsr_type in (1, 2, 3)

SELECT
    dg.gb_dg_goods_name AS gbDgGoodsName,
    dg.gb_dg_nx_father_img AS gbDgNxFatherImg,
    dg.gb_dg_goods_standardname AS gbDgGoodsStandardname,
    gsr.gb_dgsr_gb_dis_goods_id AS gbDistributerGoodsId,
    IFNULL(ROUND(SUM(CASE WHEN gsr.gb_dgsr_type = 1 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 1), 0) AS goodsProduceTotal,
    IFNULL(ROUND(SUM(CASE WHEN gsr.gb_dgsr_type = 2 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 1), 0) AS goodsWasteTotal,
    IFNULL(ROUND(SUM(CASE WHEN gsr.gb_dgsr_type = 3 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 1), 0) AS goodsLossTotal
FROM gb_department_goods_stock_reduce gsr
LEFT JOIN gb_department gd ON gd.gb_department_id = gsr.gb_dgsr_gb_department_id
LEFT JOIN gb_distributer_goods dg ON dg.gb_distributer_goods_id = gsr.gb_dgsr_gb_dis_goods_id



            gsr.gb_dgsr_type = #{params.reduceTypeFilter}


            gsr.gb_dgsr_type in (1, 2, 3)



        AND gsr.gb_dgsr_gb_distributer_id = #{params.disId}


        AND gsr.gb_dgsr_gb_department_id = #{params.depId}


        AND gd.gb_department_type = #{params.depType}


        AND gsr.gb_dgsr_date >= #{params.startDate}


        AND gsr.gb_dgsr_date <= #{params.stopDate}


        AND (
            gsr.gb_dgsr_gb_dis_goods_great_id = #{params.disGoodsGreatId}
            OR dg.gb_dg_dfg_goods_great_id = #{params.disGoodsGreatId}
        )


GROUP BY gsr.gb_dgsr_gb_dis_goods_id, dg.gb_dg_goods_name, dg.gb_dg_nx_father_img, dg.gb_dg_goods_standardname


        ORDER BY (
            IFNULL(SUM(CASE WHEN gsr.gb_dgsr_type = 1 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 0)
            + IFNULL(SUM(CASE WHEN gsr.gb_dgsr_type = 2 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 0)
            + IFNULL(SUM(CASE WHEN gsr.gb_dgsr_type = 3 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 0)
        ) DESC


        ORDER BY IFNULL(SUM(CASE WHEN gsr.gb_dgsr_type = 1 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 0) DESC


        ORDER BY IFNULL(SUM(CASE WHEN gsr.gb_dgsr_type = 2 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 0) DESC


        ORDER BY IFNULL(SUM(CASE WHEN gsr.gb_dgsr_type = 3 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 0) DESC


        ORDER BY (
            IFNULL(SUM(CASE WHEN gsr.gb_dgsr_type = 1 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 0)
            + IFNULL(SUM(CASE WHEN gsr.gb_dgsr_type = 2 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 0)
            + IFNULL(SUM(CASE WHEN gsr.gb_dgsr_type = 3 THEN gsr.gb_dgsr_subtotal ELSE 0 END), 0)
        ) DESC



    LIMIT #{params.offset}, #{params.limit}

SELECT gsr.*
FROM gb_department_goods_stock_reduce gsr
LEFT JOIN gb_department gd ON gd.gb_department_id = gsr.gb_dgsr_gb_department_id
LEFT JOIN gb_distributer_goods dg ON dg.gb_distributer_goods_id = gsr.gb_dgsr_gb_dis_goods_id


        AND gsr.gb_dgsr_gb_dis_goods_id IN

            #{gid}




            AND gsr.gb_dgsr_type = #{params.reduceTypeFilter}


            AND gsr.gb_dgsr_type IN (1, 2, 3)



        AND gsr.gb_dgsr_gb_distributer_id = #{params.disId}


        AND gsr.gb_dgsr_gb_department_id = #{params.depId}


        AND gd.gb_department_type = #{params.depType}


        AND gsr.gb_dgsr_date >= #{params.startDate}


        AND gsr.gb_dgsr_date <= #{params.stopDate}


        AND (
            gsr.gb_dgsr_gb_dis_goods_great_id = #{params.disGoodsGreatId}
