        )


ORDER BY gsr.gb_dgsr_gb_dis_goods_id, gsr.gb_dgsr_gb_department_id, gsr.gb_dgsr_date DESC,
         gsr.gb_department_goods_stock_reduce_id DESC

SELECT
    gb_dgsr_date AS date,
    IFNULL(ROUND(SUM(gb_dgsr_subtotal), 1), 0) AS total
FROM gb_department_goods_stock_reduce
WHERE 1=1

    AND gb_dgsr_date >= #{params.startDate}


    AND gb_dgsr_date <= #{params.stopDate}


    AND gb_dgsr_gb_distributer_id = #{params.disId}

GROUP BY gb_dgsr_date
ORDER BY gb_dgsr_date

